class Solution {public:int maxDifference(string s,int k){int n=s.size(),ans=INT_MIN;for(char a='0';a<='4';++a)for(char b='0';b<='4';++b)if(a!=b){
 int pa=0,pb=0,la=0,lb=0,left=0;int best[2][2]={{INT_MAX/4,INT_MAX/4},{INT_MAX/4,INT_MAX/4}};
 for(int r=0;r<n;++r){pa+=s[r]==a;pb+=s[r]==b;
 while(r-left+1>=k&&pb-lb>=2){best[la&1][lb&1]=min(best[la&1][lb&1],la-lb);la+=s[left]==a;lb+=s[left]==b;++left;}
 int v=best[1-(pa&1)][pb&1];if(v<INT_MAX/4)ans=max(ans,pa-pb-v);
 }}return ans;}};
